window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-3ab4986515e85ce5"]={"versions": [{"id": "FIG-3ab4986515e85ce5", "releases": ["R4.1.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Spezifikation des AUTOSAR-ECU-Konfigurationsschemas (BSW ECU Configuration Description) für das Modul Diagnostic Event Manager (<code>Dem</code>) im Rahmen der Classic Platform. Dargestellt ist die Metamodell-Struktur des Konfigurationscontainers <code>DemEventParameter</code> (Teil 1) mit seinen Kind-Parametern, Sub-Containern und Referenzen gemäß AUTOSAR-ECUC-Metamodell.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Zentraler Container ist <code>DemEventParameter</code> (<code>EcucParamConfContainerDef</code>, Multiplizität 1..65535). Enthaltene Kind-Elemente sind:</p>\n<ul class=\"fig-list\"><li>Parameter:\n<ul class=\"fig-list\"><li><code>DemEventId</code> (<code>EcucIntegerParamDef</code>, Multiplizität 1..1, min = 1, max = 65535, symbolicNameValue = true)\n</li><li><code>DemEventKind</code> (<code>EcucEnumerationParamDef</code>, Multiplizität 1..1) mit den Literalen <code>DEM_EVENT_KIND_SWC</code> und <code>DEM_EVENT_KIND_BSW</code>\n</li><li><code>DemEventAvailable</code> (<code>EcucBooleanParamDef</code>, Multiplizität 1..1)\n</li><li><code>DemEventFailureCycleCounterThreshold</code> (<code>EcucIntegerParamDef</code>, Multiplizität 0..1, min = 1, max = 255)\n</li></ul>\n</li><li>Sub-Container:\n<ul class=\"fig-list\"><li><code>DemCallbackInitMForE</code> (<code>EcucParamConfContainerDef</code>, Multiplizität 0..1) mit Parameter <code>DemCallbackInitMForEFnc</code> (<code>EcucFunctionNameDef</code>, Multiplizität 0..1)\n</li><li><code>DemCallbackEventStatusChanged</code> (<code>EcucParamConfContainerDef</code>, Multiplizität 0..*) mit Parameter <code>DemCallbackEventStatusChangedFnc</code> (<code>EcucFunctionNameDef</code>, Multiplizität 0..1)\n</li><li><code>DemCallbackClearEventAllowed</code> (<code>EcucParamConfContainerDef</code>, Multiplizität 0..1) mit Parameter <code>DemCallbackClearEventAllowedFnc</code> (<code>EcucFunctionNameDef</code>, Multiplizität 0..1) und Parameter <code>DemClearEventAllowedBehavior</code> (<code>EcucEnumerationParamDef</code>, Multiplizität 1..1, defaultValue = DEM_NO_STATUS_BYTE_CHANGE) mit den Literalen <code>DEM_NO_STATUS_BYTE_CHANGE</code> und <code>DEM_ONLY_THIS_CYCLE_AND_READINESS</code>\n</li></ul>\n</li><li>Referenzen:\n<ul class=\"fig-list\"><li><code>DemOperationCycleRef</code> (<code>EcucReferenceDef</code>, Ziel: <code>DemOperationCycle</code> mit Multiplizität 1..256)\n</li><li><code>DemEventFailureCycleRef</code> (<code>EcucReferenceDef</code>, Multiplizität 0..1, Ziel: <code>DemOperationCycle</code>)\n</li><li><code>DemEnableConditionGroupRef</code> (<code>EcucReferenceDef</code>, Multiplizität 0..1, Ziel: <code>DemEnableConditionGroup</code> mit Multiplizität 0..255)\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Als statisches ECUC-Klassendiagramm beschreibt das Diagramm keine Laufzeitsequenzen. Konfigurationsseitig bestimmen die Elemente Callback-Trigger (<code>InitMonitorForEvent</code>, Statusänderungen, Löschberechtigung) sowie Abhängigkeiten von Operationszyklen, Fehlerzyklen und Freigabebedingungen (<code>DemEnableConditionGroup</code>) bei der Ereignisqualifizierung und Fehlerspeicherung im Dem.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Verbindliche Konfigurationsstruktur für BSW- und SW-C-Diagnoseereignisse. Jeder Event-Parameter verlangt eine eindeutige symbolische Event-ID, eine Zuordnung zu BSW oder SW-C und eine primäre Zuordnung zu einem Betriebszyklus (<code>DemOperationCycleRef</code>). Optional können spezifische Fehlerbetriebszyklen (<code>DemEventFailureCycleRef</code>) und Zählerschwellwerte (<code>DemEventFailureCycleCounterThreshold</code>) für die Fehlereignisqualifizierung über mehrere Zyklen definiert werden.</p>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-807e48bd84dde6f6", "releases": ["R4.2.2"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Spezifikation des AUTOSAR-ECU-Konfigurationsschemas (BSW ECU Configuration Description) für das Modul Diagnostic Event Manager (<code>Dem</code>) im Rahmen der Classic Platform. Dargestellt ist die Metamodell-Struktur des Konfigurationscontainers <code>DemEventParameter</code> (Teil 1) mit seinen Kind-Parametern, Sub-Containern und Referenzen gemäß AUTOSAR-ECUC-Metamodell.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Zentraler Container ist <code>DemEventParameter</code> (<code>EcucParamConfContainerDef</code>, Multiplizität 1..65535). Enthaltene Kind-Elemente sind:</p>\n<ul class=\"fig-list\"><li>Parameter:\n<ul class=\"fig-list\"><li><code>DemEventId</code> (<code>EcucIntegerParamDef</code>, Multiplizität 1..1, min = 1, max = 65535, symbolicNameValue = true)\n</li><li><code>DemEventKind</code> (<code>EcucEnumerationParamDef</code>, Multiplizität 1..1) mit den Literalen <code>DEM_EVENT_KIND_SWC</code> und <code>DEM_EVENT_KIND_BSW</code>\n</li><li><code>DemEventAvailable</code> (<code>EcucBooleanParamDef</code>, Multiplizität 1..1)\n</li><li><code>DemEventFailureCycleCounterThreshold</code> (<code>EcucIntegerParamDef</code>, Multiplizität 1..1, min = 0, max = 255, defaultValue = 0)\n</li></ul>\n</li><li>Sub-Container:\n<ul class=\"fig-list\"><li><code>DemCallbackInitMForE</code> (<code>EcucParamConfContainerDef</code>, Multiplizität 0..1) mit Parameter <code>DemCallbackInitMForEFnc</code> (<code>EcucFunctionNameDef</code>, Multiplizität 0..1)\n</li><li><code>DemCallbackEventStatusChanged</code> (<code>EcucParamConfContainerDef</code>, Multiplizität 0..*) mit Parameter <code>DemCallbackEventStatusChangedFnc</code> (<code>EcucFunctionNameDef</code>, Multiplizität 0..1)\n</li><li><code>DemCallbackClearEventAllowed</code> (<code>EcucParamConfContainerDef</code>, Multiplizität 0..1) mit Parameter <code>DemCallbackClearEventAllowedFnc</code> (<code>EcucFunctionNameDef</code>, Multiplizität 0..1) und Parameter <code>DemClearEventAllowedBehavior</code> (<code>EcucEnumerationParamDef</code>, Multiplizität 1..1, defaultValue = DEM_NO_STATUS_BYTE_CHANGE) mit den Literalen <code>DEM_NO_STATUS_BYTE_CHANGE</code> und <code>DEM_ONLY_THIS_CYCLE_AND_READINESS</code>\n</li></ul>\n</li><li>Referenzen:\n<ul class=\"fig-list\"><li><code>DemOperationCycleRef</code> (<code>EcucReferenceDef</code>, Ziel: <code>DemOperationCycle</code> mit Multiplizität 1..256)\n</li><li><code>DemEnableConditionGroupRef</code> (<code>EcucReferenceDef</code>, Multiplizität 0..1, Ziel: <code>DemEnableConditionGroup</code> mit Multiplizität 0..255)\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Als statisches ECUC-Klassendiagramm beschreibt das Diagramm keine Laufzeitsequenzen. Konfigurationsseitig bestimmen die Elemente Callback-Trigger (<code>InitMonitorForEvent</code>, Statusänderungen, Löschberechtigung) sowie Abhängigkeiten von Operationszyklen, Fehlerzyklen und Freigabebedingungen (<code>DemEnableConditionGroup</code>) bei der Ereignisqualifizierung und Fehlerspeicherung im Dem.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Verbindliche Konfigurationsstruktur für BSW- und SW-C-Diagnoseereignisse. Jeder Event-Parameter verlangt eine eindeutige symbolische Event-ID, eine Zuordnung zu BSW oder SW-C und eine primäre Zuordnung zu einem Betriebszyklus (<code>DemOperationCycleRef</code>). Der Schwellwert <code>DemEventFailureCycleCounterThreshold</code> ist verpflichtend mit Wertebereich 0..255 und Default 0 anzugeben. Eine separate Referenzierung eines abweichenden Fehlerzyklus am Event entfällt.</p>", "model": "gemini-3.8-flash (via agy)"}], "trans": [{"from": "FIG-3ab4986515e85ce5", "to": "FIG-807e48bd84dde6f6", "fr": "R4.1.3", "tr": "R4.2.2", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li>Referenz <code>DemEventFailureCycleRef</code> (<code>EcucReferenceDef</code> mit Multiplizität 0..1 und Ziel <code>DemOperationCycle</code>) entfernt.\n</li><li>Parameter <code>DemEventFailureCycleCounterThreshold</code> (<code>EcucIntegerParamDef</code>): Wertebereich von <code>[1..255]</code> auf <code>[0..255]</code> erweitert, Multiplizität von optional (0..1) auf verpflichtend (1..1) geändert und Standardwert <code>defaultValue = 0</code> hinzugefügt.\n</li></ul>"}]};
